import { join, dirname } from "path";


import {
  DataType,
  JsExternal,
  open,
  close,
  define,
  arrayConstructor,
  restorePointer,
  wrapPointer,
  unwrapPointer,
  createPointer,
  freePointer,
  isNullPointer,
  PointerType,
} from 'ffi-rs';
